local a=require("fcs.io.hwconfig")local b=require("fcs.io.cfgspec")local c={}function c.kindForPath(d)d=tostring(d or""):gsub("\\","/")local e=d:match("([^/]+)$")or d;if e=="eh2_devbind.tbl"then return"devbind"end;if e=="eh2_senscal.tbl"then return"senscal"end;if e=="eh2_tuning.tbl"then return"tuning"end;if e=="eh2_fuelcal.tbl"then return"fuelcal"end;if e=="eh2_ui_config.tbl"then return"ui"end;if e=="eh2_hw_config.tbl"then return"fused"end;return"fused"end;function c.load(d)if not fs.exists(d)or fs.isDir(d)then return nil,false,nil end;local f=fs.open(d,"r")if not f then return nil,true,"could not open"end;local g=f.readAll()f.close()local h=textutils.unserialise(g or"")if type(h)~="table"then return nil,true,"not a table"end;return h,true,nil end;function c.withDefaults(h,d)local i=d and c.kindForPath(d)or"fused"if i=="devbind"or i=="senscal"or i=="tuning"or i=="fuelcal"then return b.merge(i,h)end;if i=="ui"then return require("ui.config").withDefaults(h)end;return a.merge(h or{},a.defaults())end;function c.save(d,h)local j=d..".tmp"local f=fs.open(j,"w")if not f then return false,"could not open tmp"end;f.write(textutils.serialise(h))f.close()if fs.exists(d)then fs.delete(d)end;fs.move(j,d)return true,nil end;return c